import sys

def main():
    # Read all tokens from standard input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])

    # The smallest valid alkane has 5 vertices (1 center, 4 leaves)
    if N < 5:
        print(-1)
        return

    adj = [[] for _ in range(N + 1)]
    idx = 1

    # Build the adjacency list
    for _ in range(N - 1):
        a = int(input_data[idx])
        b = int(input_data[idx+1])
        idx += 2
        adj[a].append(b)
        adj[b].append(a)

    # Identify vertices that can act as internal nodes in the alkane
    good = [False] * (N + 1)
    has_good = False
    for i in range(1, N + 1):
        if len(adj[i]) >= 4:
            good[i] = True
            has_good = True

    if not has_good:
        print(-1)
        return

    # Use bytearray for a fast and memory-efficient visited array
    visited = bytearray(N + 1)
    best = 0

    # Find the largest connected component of "good" vertices using iterative DFS
    for i in range(1, N + 1):
        if good[i] and not visited[i]:
            stack = [i]
            visited[i] = 1
            size = 0
            while stack:
                u = stack.pop()
                size += 1
                for v in adj[u]:
                    if good[v] and not visited[v]:
                        visited[v] = 1
                        stack.append(v)
            if size > best:
                best = size

    # An alkane component of size k will have k internal nodes and 2k + 2 leaves
    # Total vertices = k + (2k + 2) = 3k + 2
    print(3 * best + 2)

if __name__ == '__main__':
    main()
